import{_ as s,o as n,a as p,b as l}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"Layout","link":"/api/SIMD-API/tensor_api/layout/layout_structure"},{"text":"make_pattern_layout","link":"/api/SIMD-API/tensor_api/layout/make_pattern_layout"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/layout/make_pattern_layout.md","filePath":"api/SIMD-API/tensor_api/layout/make_pattern_layout.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787967772000}'),t={name:"api/SIMD-API/tensor_api/layout/make_pattern_layout.md"};function e(c,a,i,d,r,o){return n(),p("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>make_pattern_layout</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p>make_pattern_layout用于根据shape、stride、LayoutPattern和Trait构造带布局模式信息的layout对象。</p><p>与<a href="./make_layout.html">make_layout</a>相比，make_pattern_layout除了保存shape和stride外，还会在layout类型中附加布局模式LayoutPattern和Trait信息。</p><p>Trait用于描述C0粒度等布局特征。若使用<code>layout_trait&lt;T, C0&gt;</code>或<code>layout_trait_default&lt;T&gt;</code>写法，T仅作为兼容占位或C0推导依据，不作为Tensor的数据类型信息保存。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">LayoutPattern</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Trait</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Shape</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Stride</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_pattern_layout</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Shape</span><span class="o">&amp;</span><span class="w"> </span><span class="n">shape</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Stride</span><span class="o">&amp;</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名称</th><th align="left">类型</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">LayoutPattern</td><td align="left">输入</td><td align="left">布局模式类型，用于标记layout的格式信息。</td></tr><tr><td align="left">Trait</td><td align="left">输入</td><td align="left">布局trait类型，用于标记C0粒度等布局特征。</td></tr><tr><td align="left">Shape</td><td align="left">输入</td><td align="left">shape的类型，要求为元组(tuple)类型。</td></tr><tr><td align="left">Stride</td><td align="left">输入</td><td align="left">stride的类型，要求为元组(tuple)类型。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th align="left">参数名称</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">shape</td><td align="left">输入</td><td align="left">描述逻辑形状的元组对象，可由<a href="./make_shape.html">make_shape</a>构造。</td></tr><tr><td align="left">stride</td><td align="left">输入</td><td align="left">描述各维步长的元组对象，可由<a href="./make_stride.html">make_stride</a>构造。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回<code>layout&lt;Shape, Stride, Std::tuple&lt;LayoutPattern, Trait&gt;&gt;</code>类型对象。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>shape和stride必须满足layout构造要求，即都为元组类型。</li><li>LayoutPattern应为合法的布局模式类型，例如nz_layout_ptn、zn_layout_ptn、nd_layout_ptn、dn_layout_ptn等。</li><li>Trait应与LayoutPattern及后续使用场景匹配，否则可能导致后续格式检查或路由失败。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>

<span class="c1">// 示例1：构造带NZ布局模式的layout</span>
<span class="k">auto</span><span class="w"> </span><span class="n">layout1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_pattern_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;&gt;&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">make_shape</span><span class="p">(</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">),</span><span class="w"> </span><span class="n">make_shape</span><span class="p">(</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">)),</span>
<span class="w">    </span><span class="n">make_stride</span><span class="p">(</span><span class="n">make_stride</span><span class="p">(</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">),</span><span class="w"> </span><span class="n">make_stride</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="p">))</span>
<span class="p">);</span>

<span class="c1">// 示例2：构造带ND布局模式的layout</span>
<span class="k">auto</span><span class="w"> </span><span class="n">layout2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_pattern_layout</span><span class="o">&lt;</span><span class="n">nd_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait</span><span class="o">&lt;</span><span class="n">Std</span><span class="o">::</span><span class="n">ignore_t</span><span class="p">,</span><span class="w"> </span><span class="n">_1</span><span class="o">&gt;&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">make_shape</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">64</span><span class="p">),</span>
<span class="w">    </span><span class="n">make_stride</span><span class="p">(</span><span class="mi">64</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span>
<span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const _=s(t,[["render",e]]);export{u as __pageData,_ as default};
